endmodule

module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]   counter50;
    logic   [31:0]   counter72;

    always_ff @(posedge clk50) begin
        if (counter50 < COUNT_LIMIT) begin
            counter50 <= counter50 + 1;
        end
    end

    always_ff @(posedge clk72) begin
        if (counter72 < COUNT_LIMIT) begin
            counter72 <= counter72 + 1;
        end
    end

    assign led[1] = counter50[31];
    assign led[0] = counter72[31];

    assign pmod[7] = counter50[29];
    assign pmod[6] = counter50[28];
    assign pmod[5] = counter50[27];
    assign pmod[4] = counter50[26];
    assign pmod[3] = counter50[25];
    assign pmod[2] = counter50[24];
    assign pmod[1] = counter50[23];
    assign pmod[0] = counter50[22];

endmodule

