module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [31:0] counter;
    reg [31:0] index;
    reg [31:0] keypress_array [0:15];
    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            keypress_array[i] = i;
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
        end else begin
            if (counter == 20) begin
                counter <= 0;
                index <= index + 1;
            end else begin
                counter <= counter + 1;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            keypress <= 0;
        end else begin
            if (index == 15) begin
                keypress <= keypress_array[15];
            end else begin
                keypress <= keypress_array[index];
            end
        end
    end
endmodule

