	output logic              i0_valid,
	input                     i0_ready
);
logic  [WIDTH-1:0] dat0;
logic              dat0_valid;
logic              dat0_ready;
logic  [WIDTH-1:0] dat1;
logic              dat1_valid;
logic              dat1_ready;
logic  [2:0] state;
logic  [2:0] next_state;

assign t0_ready = dat0_ready;
assign i0_data = dat1;
assign i0_valid = dat1_valid;

always_ff @(posedge clk) begin
	if (!reset_n) begin
		dat0 <= '0;
		dat0_valid <= 0;
		dat0_ready <= 0;
		dat1 <= '0;
		dat1_valid <= 0;
		dat1_ready <= 0;
		state <= S0;
	end else begin
		dat0 <= dat0_valid ? t0_data : '0;
		dat0_valid <= t0_valid;
		dat0_ready <= i0_ready;
		dat1 <= dat1_valid ? t0_data : '0;
		dat1_valid <= t0_valid;
		dat1_ready <= i0_ready;
		state <= next_state;
	end
end

always_comb begin
	case (state)
		S0: begin
			next_state = S1;
			if (t0_valid && i0_ready) begin
				next_state = S2;
			end
		end
		S1: begin
			next_state = S2;
			if (!t0_valid) begin
				next_state = S0;
			end
		end
		S2: begin
			next_state = S3;
			if (!t0_valid) begin
				next_state = S0;
			end
		end
		S3: begin
			next_state = S4;
			if (!t0_valid) begin
				next_state = S0;
			end
		end
		S4: begin
			next_state = S0;
			if (t0_valid && i0_ready) begin
				next_state = S2;
			end
		end
		default: begin
			next_state = S0;
		end
	endcase
end

endmodule

