module tone(
    input CLK,
    input[31:0] period, 
    output reg tone_out
    );
parameter CLK_F = 32;
    reg[31:0] prescaler = 0;
    reg[31:0] counter = 0;
    always @(posedge CLK) begin
        if (prescaler == CLK_F - 1) begin
            prescaler <= 0;
            counter <= counter + 1;
        end else begin
            prescaler <= prescaler + 1;
        end
        if (counter == period) begin
            counter <= 0;
            tone_out <= ~tone_out;
        end
    end
endmodule

module upcounter (Resetn, Clock, E, Q);
    input Resetn, Clock, E;
    output reg [2:0] Q;
always @(negedge Resetn or posedge Clock) begin
        if (Resetn == 0) begin
            Q <= 0;
        end else if (E == 1) begin
            Q <= Q + 1;
        end
    end
endmodule

