module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [1:0] reset=2'b00,
idle=2'b01,
running=2'b10,
complete=2'b11;
reg [1:0] current_state;
reg [1:0] next_state;
  always @(posedge clk, negedge resetn) begin
    if((~resetn)) begin
      current_state <= reset;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    reset : begin
      next_state <= idle;
    end
    idle : begin
      if((go)) begin
        next_state <= running;
      end
      else begin
        next_state <= idle;
      end
    end
    running : begin
      if((WREADY)) begin
        next_state <= running;
      end
      else begin
        next_state <= idle;
      end
    end
    complete : begin
      if((WREADY)) begin
        next_state <= complete;
      end
      else begin
        next_state <= idle;
      end
    end
    default : begin
      next_state <= idle;
    end
    endcase
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    reset : begin
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
      done <= 1'b0;
    end
    idle : begin
      if((go)) begin
        WDATA <= data;
        WSTRB <= 4'hF;
        WVALID <= 1'b1;
        done <= 1'b0;
      end
      else begin
        WDATA <= 32'h00000000;
        WSTRB <= 4'h0;
        WVALID <= 1'b0;
        done <= 1'b0;
      end
    end
    running : begin
      if((WREADY)) begin
        WDATA <= data;
        WSTRB <= 4'hF;
        WVALID <= 1'b1;
        done <= 1'b0;
      end
      else begin
        WDATA <= 32'h00000000;
        WSTRB <= 4'h0;
        WVALID <= 1'b0;
        done <= 1'b0;
      end
    end
    complete : begin
      if((WREADY)) begin
        WDATA <= data;
        WSTRB <= 4'hF;
        WVALID <= 1'b1;
        done <= 1'b1;
      end
      else begin
        WDATA <= 32'h00000000;
        WSTRB <= 4'h0;
        WVALID <= 1'b0;
        done <= 1'b1;
      end
    end
    default : begin
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
      done <= 1'b0;
    end
    endcase
  end
endmodule

