module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
reg [1:0] state = IDLE;
reg [35:0] data0_o, data1_o;
reg src0_rdy_o, src1_rdy_o;
reg eof;
assign dst_rdy_o = (state == DATA0) || (state == DATA1);
assign src0_rdy_o = (state == DATA0) && src_rdy_i;
assign src1_rdy_o = (state == DATA1) && src_rdy_i;
assign eof = (state == DATA0) ? data_i[35] : data_i[35];
always @ (posedge clk)
  if (clear)
    state <= IDLE;
  else if (state == IDLE)
    if (match_data == data_i[35:match_data])
      state <= DATA0;
    else if (match_mask == data_i[35:match_mask])
      state <= DATA1;
  else if (state == DATA0)
    if (dst0_rdy_i)
      state <= IDLE;
    else if (eof)
      state <= IDLE;
  else if (state == DATA1)
    if (dst1_rdy_i)
      state <= IDLE;
    else if (eof)
      state <= IDLE;
always @ (posedge clk)
  if (clear)
    data0_o <= 0;
  else if (state == DATA0)
    data0_o <= data_i;
always @ (posedge clk)
  if (clear)
    data1_o <= 0;
  else if (state == DATA1)
    data1_o <= data_i;
endmodule

