module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW+DW-1:0] addr_req;
reg [AW-1:0]    cached_addr0;
reg [DW-1:0]    cached_data0;
reg [AW+DW-1:0] cached_addr1;
reg [DW-1:0]    cached_data1;
reg [AW-1:0]    subaddr;
reg             good;

always @* begin
    addr_req = {addr, {DW{1'b0}}};
    if (DW == 8) begin
        addr_req = {addr, 1'b0};
    end
    if (DW == 16) begin
        addr_req = {addr, 1'b0, 1'b0};
    end
    if (DW == 32) begin
        addr_req = {addr, 1'b0, 1'b0, 1'b0};
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        cached_addr0 <= {AW{1'b0}};
        cached_data0 <= {DW{1'b0}};
        cached_addr1 <= {AW{1'b0}};
        cached_data1 <= {DW{1'b0}};
        subaddr <= {AW{1'b0}};
        good <= 1'b0;
    end else begin
        if (addr_ok && !we) begin
            cached_addr0 <= addr_req;
            cached_data0 <= din;
            good <= 1'b1;
        end
        if (addr_ok && we) begin
            cached_addr1 <= addr_req;
            cached_data1 <= din;
            good <= 1'b0;
        end
        if (addr_ok && !we && !good) begin
            subaddr <= addr_req[AW-1:0];
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        req <= 1'b0;
        data_ok <= 1'b0;
        sdram_addr <= {AW{1'b0}};
        dout <= {DW{1'b0}};
    end else begin
        if (addr_ok && !we) begin
            req <= 1'b0;
            data_ok <= 1'b1;
            sdram_addr <= {offset, cached_addr0};
            dout <= cached_data0;
        end
        if (addr_ok && we) begin
            req <= 1'b1;
            data_ok <= 1'b0;
            sdram_addr <= {offset, cached_addr1};
            dout <= cached_data1;
        end
        if (addr_ok && !we && !good) begin
            req <= 1'b0;
            data_ok <= 1'b1;
            sdram_addr <= {offset, subaddr};
            dout <= din;
        end
    end
end

endmodule

