module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [6:0] current;
reg [6:0] next;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      current <= 7'b0000000;
    end else begin
      current <= next;
    end
  end
  always @(current, A, D, WR, RD) begin
    case(A)
    3'b000 : begin
      next <= current;
    end
    3'b001 : begin
      next <= D;
    end
    3'b010 : begin
      next <= current;
    end
    3'b011 : begin
      next <= current;
    end
    3'b100 : begin
      next <= current;
    end
    3'b101 : begin
      next <= current;
    end
    3'b110 : begin
      next <= current;
    end
    3'b111 : begin
      next <= current;
    end
    default : begin
      next <= current;
    end
    endcase
  end
  always @(current, A, D, WR, RD) begin
    case(A)
    3'b000 : begin
      WCTRL <= 1'b0;
    end
    3'b001 : begin
      WCTRL <= 1'b1;
    end
    3'b010 : begin
      WCTRL <= 1'b0;
    end
    3'b011 : begin
      WCTRL <= 1'b0;
    end
    3'b100 : begin
      WCTRL <= 1'b0;
    end
    3'b101 : begin
      WCTRL <= 1'b0;
    end
    3'b110 : begin
      WCTRL <= 1'b0;
    end
    3'b111 : begin
      WCTRL <= 1'b0;
    end
    default : begin
      WCTRL <= 1'b0;
    end
    endcase
  end
  assign Y = current;
endmodule

