module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    wire scan_ready;
    assign scan_ready = counter == 4'b1111;
    always @(negedge i_clock) begin
        if (reset) begin
            scan_code <= 8'b0;
            counter <= 4'b0;
        end else begin
            scan_code[counter] <= i_data;
            counter <= counter + 1'b1;
            if (counter == 4'b1111) begin
                if (scan_code[8] ^ scan_code[7] ^ scan_code[6] ^ scan_code[5] ^ scan_code[4] ^ scan_code[3] ^ scan_code[2] ^ scan_code[1] ^ scan_code[0]) begin
                    scan_code <= 8'b0;
                    counter <= 4'b0;
                end
            end
        end
    end
endmodule

