module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );
reg [31:0] Divisor;
	reg [31:0] Divider;
	reg [31:0] remainder;
	reg [31:0] result;
	reg [31:0] counter;
	reg [31:0] done;
	
	always @(posedge CLK) begin
		if(Divisor != 0) begin
			Divisor <= Divisor;
			Divider <= Divider;
			remainder <= remainder;
			result <= result;
			counter <= counter;
			done <= done;
		end
		else begin
			Divisor <= 0;
			Divider <= 0;
			remainder <= 0;
			result <= 0;
			counter <= 0;
			done <= 0;
		end
	end
	always @(posedge CLK) begin
		if(Divisor != 0) begin
			if(Divider != 0) begin
				if(remainder >= Divider) begin
					remainder <= remainder - Divider;
					result <= result + 1;
					counter <= counter + 1;
				end
				else begin
					remainder <= remainder;
					result <= result;
					counter <= counter;
				end
			end
			else begin
				remainder <= 0;
				result <= 0;
				counter <= 0;
			end
		end
		else begin
			remainder <= 0;
			result <= 0;
			counter <= 0;
		end
	end
	always @(posedge CLK) begin
		if(Divisor != 0) begin
			if(Divider != 0) begin
				if(remainder >= Divider) begin
					done <= 0;
				end
				else begin
					done <= 1;
				end
			end
			else begin
				done <= 0;
			end
		end
		else begin
			done <= 0;
		end
	end
endmodule

