output [2*size-1 : 0] pdt;
parameter size = 16;
parameter level = 4;

reg [size-1 : 0] a_int;
reg [size-1 : 0] b_int;
reg [2*size-1 : 0] pdt_int [0 : level-1];

integer i;

always @(posedge clk) begin
    a_int <= a;
    b_int <= b;
end

always @(posedge clk) begin
    for (i = 0; i < level-1; i = i + 1) begin
        pdt_int[i+1] <= pdt_int[i] * a_int + b_int;
    end
    pdt_int[level-1] <= pdt_int[level-2] * a_int + b_int;
end

assign pdt = pdt_int[level-1];

endmodule

