module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
reg [3:0] maybe_full;
  wire do_enq;
  wire do_deq;
  assign do_enq = io_enq_valid & io_enq_ready;
  assign do_deq = io_deq_valid & io_deq_ready;
  assign io_enq_ready = 1'b1;
  assign io_deq_valid = 1'b0;
  assign io_deq_bits_tl_state_size = maybe_full;
  assign io_deq_bits_tl_state_source = 2'b00;
  always @(posedge clock) begin
    if (reset) begin
      maybe_full <= 4'b0000;
    end else begin
      if (do_enq) begin
        maybe_full <= maybe_full + 4'b0001;
      end
      if (do_deq) begin
        maybe_full <= maybe_full - 4'b0001;
      end
    end
  end
endmodule

