module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0]   state;

assign s_ready = state == ONE || state == TWO;

always @ (posedge clk or posedge reset)
    if (reset)
        state <= ZERO;
    else
        case (state)
            ZERO: begin
                if (s_valid)
                    state <= ONE;
                else
                    state <= ZERO;
            end
            ONE: begin
                if (m_ready)
                    state <= TWO;
                else
                    state <= ONE;
            end
            TWO: begin
                if (s_valid)
                    state <= ONE;
                else
                    state <= TWO;
            end
        endcase

always @ (posedge clk or posedge reset)
    if (reset)
        data_p1 <= {N{1'b0}};
    else
        case (state)
            ZERO: data_p1 <= {N{1'b0}};
            ONE:  data_p1 <= s_data;
            TWO:  data_p1 <= data_p2;
        endcase

always @ (posedge clk or posedge reset)
    if (reset)
        data_p2 <= {N{1'b0}};
    else
        case (state)
            ZERO: data_p2 <= {N{1'b0}};
            ONE:  data_p2 <= data_p1;
            TWO:  data_p2 <= data_p1;
        endcase

assign m_data = state == ONE ? data_p1 : data_p2;
assign m_valid = state == ONE;

endmodule

