module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [3:0] counter;
    reg [7:0] dout_parallel_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            dout_parallel_reg <= 0;
            dout_valid <= 0;
        end else begin
            if (din_valid) begin
                dout_parallel_reg <= {dout_parallel_reg[6:0], din_serial};
                counter <= counter + 1;
                if (counter == 8) begin
                    dout_valid <= 1;
                    counter <= 0;
                end
            end else begin
                dout_valid <= 0;
            end
        end
    end
    assign dout_parallel = dout_parallel_reg;
endmodule

