input [15:0] b_r,
input [15:0] b_i,
input [15:0] w_r,
input [15:0] w_i,
output [15:0] x_r,
output [15:0] x_i,
output [15:0] y_r,
output [15:0] y_i);
wire [31:0] a_r2;
wire [31:0] a_i2;
wire [31:0] b_r2;
wire [31:0] b_i2;
wire [31:0] w_r2;
wire [31:0] w_i2;
wire [31:0] x_r2;
wire [31:0] x_i2;
wire [31:0] y_r2;
wire [31:0] y_i2;
assign a_r2 = a_r;
assign a_i2 = a_i;
assign b_r2 = b_r;
assign b_i2 = b_i;
assign w_r2 = w_r;
assign w_i2 = w_i;
assign x_r = x_r2[31:16];
assign x_i = x_i2[31:16];
assign y_r = y_r2[31:16];
assign y_i = y_i2[31:16];
assign x_r2 = (a_r2 + a_i2) + (b_r2 - b_i2) * w_r2;
assign x_i2 = (a_r2 + a_i2) - (b_r2 - b_i2) * w_i2;
assign y_r2 = (a_r2 - a_i2) + (b_r2 + b_i2) * w_r2;
assign y_i2 = (a_r2 - a_i2) - (b_r2 + b_i2) * w_i2;
endmodule

