module linear_layer (
    input [63:0] x0, x1, x2, x3, x4,
    output [63:0] o0, o1, o2, o3, o4
);
assign o0 = x0 ^ {x4, x3, x2, x1};
    assign o1 = x1 ^ {x4, x3, x2, x0};
    assign o2 = x2 ^ {x4, x3, x0, x1};
    assign o3 = x3 ^ {x4, x0, x1, x2};
    assign o4 = x4 ^ {x0, x1, x2, x3};
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
wire [16:0] tmp;
    always @* begin
        tmp = {{14{data_i[13]}},data_i};
        case(shift_i)
            0: data_o = tmp;
            1: data_o = tmp << 1;
            2: data_o = tmp << 2;
            3: data_o = tmp << 3;
        endcase
    end
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @ (a or enable)
    begin
        if (enable == 0)
            y = 8'b00000000;
        else
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] memory [0:31];
initial begin
    for (int i = 0; i < 32; i = i + 1) begin
        memory[i] = 0;
    end
end
always @(posedge clk) begin
    if (MemWrite) begin
        memory[addr] <= write_data;
    end
end
assign read_data = (MemRead) ? memory[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
wire [BITS - 1:0] enable_wires;
assign enable_wires = {ena, enable_wires};
assign out = cnt;
assign ovf = cnt == 2**BITS - 1 ? 1'b1 : 1'b0;

genvar i;
generate for (i = 0; i < BITS; i = i + 1) begin: gen
        always @(posedge clk, posedge rst) begin
            if (rst) begin
                cnt <= 0;
            end else if (ena) begin
                if (updown) begin
                    cnt <= cnt + 1;
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end
endgenerate

endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1;
	always @ (reg1) begin
		for (int i = 0; i < 16; i = i + 1) begin
			if (reg1[3 * i + 3] > 4) begin
				reg1[3 * i + 3] = reg1[3 * i + 3] + 3;
			end
			if (reg1[3 * i + 2] > 4) begin
				reg1[3 * i + 2] = reg1[3 * i + 2] + 3;
			end
			if (reg1[3 * i + 1] > 4) begin
				reg1[3 * i + 1] = reg1[3 * i + 1] + 3;
			end
			if (reg1[3 * i] > 4) begin
				reg1[3 * i] = reg1[3 * i] + 3;
			end
		end
		reg1 = reg1 >> 4;
		b = reg1[3:0];
		s = reg1[7:4];
		g = reg1[11:8];
		q = reg1[15:12];
	end
endmodule

