module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk;
reg updateclk;
reg capture;
reg update;

always @ (captnupdt or shiftnld or clk)
begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11: begin
            updateclk <= clk;
            capture  <= 1'b1;
        end
        2'b01: begin
            updateclk <= clk;
            capture  <= 1'b0;
        end
        default: begin
            mainclk <= clk;
            update  <= 1'b1;
        end
    endcase
end

initial begin
    mainclk <= 1'b0;
    updateclk <= 1'b0;
    capture <= 1'b0;
    update <= 1'b0;
end

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
reg [15:0] H_cnt;
reg Pout_de_w;
reg Pout_hs_w;
reg Pout_vs_w;
reg Rden_w;

always @(posedge I_pxl_clk or negedge I_rst_n)
begin
    if (~I_rst_n)
    begin
        V_cnt <= 0;
        H_cnt <= 0;
    end
    else
    begin
        V_cnt <= V_cnt + 1;
        H_cnt <= H_cnt + 1;
    end
end

always @*
begin
    Pout_de_w = (H_cnt < I_h_res) && (V_cnt < I_v_res);
    Pout_hs_w = (H_cnt < I_h_sync) && (V_cnt < I_v_res);
    Pout_vs_w = (H_cnt < I_h_res) && (V_cnt < I_v_sync);
    Rden_w = (H_cnt < I_rd_hres) && (V_cnt < I_rd_vres);
end

always @*
begin
    O_de = Pout_de_w;
    O_hs = Pout_hs_w;
    O_vs = Pout_vs_w;
    O_rden = Rden_w;
end

assign #1 O_de = I_hs_pol ? ~O_de : O_de;
assign #1 O_hs = I_hs_pol ? ~O_hs : O_hs;
assign #1 O_vs = I_vs_pol ? ~O_vs : O_vs;
assign #1 O_rden = I_vs_pol ? ~O_rden : O_rden;
endmodule

