module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma, undersampled_sigma;
	reg [31:0] delta;
	wire [31:0] deriv;

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
		end else begin
			if (ock) begin
				if (sdi) begin
					sigma <= sigma + 1;
				end else begin
					sigma <= sigma - 1;
				end
			end
			if (uck) begin
				if (sdi) begin
					undersampled_sigma <= undersampled_sigma + 1;
				end else begin
					undersampled_sigma <= undersampled_sigma - 1;
				end
			end
		end
	end

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			delta <= 0;
		end else begin
			if (sdi) begin
				delta <= undersampled_sigma - sigma;
			end else begin
				delta <= sigma - undersampled_sigma;
			end
		end
	end

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			deriv <= 0;
		end else begin
			if (signed_data) begin
				deriv <= delta;
			end else begin
				deriv <= delta - 1;
			end
		end
	end

	assign dout = signed_data ? deriv : {32{deriv[31]}};
