module DFF_en2(clk ,nRST, en, D, Q);
input wire [n-1:0] D;
input wire en;
input wire clk;
input wire nRST;
output reg [n-1:0] Q;
parameter n = 32;
always @(posedge clk, negedge nRST) begin
    if (!nRST) begin
      Q <= 0;
    end else if (en) begin
      Q <= D;
    end
  end
endmodule

module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg [DATA_BITS-1:0] dout;
reg [DATA_BITS-1:0] index;
reg empty_n, full_n, read, write;

assign dout = (empty_n) ? 0 : mem[index];

always @ (posedge clk or posedge aclr)
begin
    if (aclr)
    begin
        empty_n <= 1;
        full_n  <= 0;
        index  <= 0;
    end
    else
    begin
        if (write)
        begin
            if (full_n)
            begin
                empty_n <= 0;
                full_n  <= 1;
            end
            mem[index] <= din;
            index <= (index == DEPTH-1) ? 0 : index + 1;
        end
        else if (read)
        begin
            if (empty_n)
            begin
                empty_n <= 1;
                full_n  <= 0;
            end
            index <= (index == 0) ? DEPTH-1 : index - 1;
        end
    end
end

assign empty_n = (index == 0);
assign full_n  = (index == DEPTH-1);

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
); 

reg [31:0] timer;
reg pre;
  always @(posedge clk) begin
    if(timer == 32'd1000000) begin
      if(btn_input == pre) begin
        btn_output <= btn_input;
      end
      timer <= 0;
      pre <= btn_input;
    end
    else begin
      timer <= timer + 1;
    end
  end
endmodule

