module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam  IDLE = 2'b00,
             READY = 2'b01,
             RELEASE = 2'b10;

reg [1:0] state = IDLE;
reg [23:0] r_count = 0;
reg [23:0] r_size = 0;

always @(posedge clk) begin
  if (rst) begin
    state <= IDLE;
    r_count <= 0;
    r_size <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (i_ppfifo_rdy[0] && i_ppfifo_rdy[1]) begin
          state <= READY;
          r_count <= 0;
          r_size <= i_ppfifo_size;
        end
      end
      READY: begin
        if (i_h_blank) begin
          if (i_v_sync) begin
            if (r_count < r_size) begin
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end
          end
        end else begin
          if (i_v_sync) begin
            if (r_count < r_size) begin
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end
          end
          else begin
            if (r_count < r_size) begin
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end
          end
        end
        if (i_v_sync) begin
          if (r_count == r_size) begin
            state <= RELEASE;
          end
        end
      end
      RELEASE: begin
        if (i_h_sync) begin
          if (i_v_sync) begin
            if (r_count < r_size) begin
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end
          end
        end else begin
          if (i_v_sync) begin
            if (r_count < r_size) begin
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end
          end
          else begin
            if (r_count < r_size) begin
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end
          end
        end
        if (i_v_sync) begin
          if (r_count == r_size) begin
            state <= IDLE;
          end
        end
      end
      default: begin
        state <= IDLE;
        r_count <= 0;
        r_size <= 0;
      end
    endcase
  end
end

assign o_ppfifo_clk = clk;
assign o_ppfifo_act = i_ppfifo_rdy;
assign o_ppfifo_stb = i_data_en;

endmodule

