    predict_valid,
    predict_pc,
    predict_taken,
    predict_history,

    train_valid,
    train_taken,
    train_mispredicted,
    train_history,
    train_pc
);
input  clk;
input  areset;

input  predict_valid;
input  [6:0] predict_pc;
output predict_taken;
output [6:0] predict_history;

input  train_valid;
input  train_taken;
input  train_mispredicted;
input  [6:0] train_history;
input  [6:0] train_pc;
wire [6:0] train_history_next;

wire [6:0] predict_history_next;

reg [6:0] branch_history;

reg [6:0] pht [0:127];

assign predict_taken = pht[0][0];
assign predict_history = branch_history;

always @(posedge clk) begin
    if (predict_valid) begin
        branch_history <= predict_history_next;
    end
end

always @(posedge clk) begin
    if (train_valid) begin
        pht[train_pc][train_history] <= train_taken;
        if (train_mispredicted) begin
            branch_history <= train_history_next;
        end
    end
end

assign predict_history_next = pht[0][0] ? {7{1'b1}} : {7{1'b0}};
assign train_history_next = pht[train_pc][train_history] ? {7{1'b1}} : {7{1'b0}};

endmodule

