module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
reg [3:0] delay;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
            counting <= 1'b0;
            done <= 1'b0;
            delay <= 4'b0000;
        end else begin
            if (data == 1'b1 && delay == 4'b0000) begin
                delay <= 4'b1101;
                counting <= 1'b1;
            end
            if (counting) begin
                count <= count + 1;
                if (count == (delay + 1)) begin
                    counting <= 1'b0;
                    done <= 1'b1;
                end
            end
            if (ack) begin
                counting <= 1'b0;
                done <= 1'b0;
                delay <= 4'b0000;
            end
        end
    end
endmodule

