module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);
reg [2:0] Y;
  always @(posedge clk) begin
    case (Y)
      3'b000: begin
        if (x == 1'b0) begin
          Y <= 3'b000;
          z <= 1'b0;
        end
        else begin
          Y <= 3'b001;
          z <= 1'b0;
        end
      end
      3'b001: begin
        if (x == 1'b0) begin
